progressive_examples.raw_code:
// Khai báo số lượng tồn kho thực tế của mặt hàng
const productStock = 3;

// Kiểm tra điều kiện còn hàng
if (productStock > 0) {
  console.log('[THÔNG BÁO] Đủ điều kiện mua hàng. Hệ thống đang chuyển sang trang thanh toán.');
} else {
  console.log('[THÔNG BÁO] Sản phẩm tạm thời hết hàng. Quý khách vui lòng chọn sản phẩm khác.');
}

const productStock = 10;
const orderTotal = 320000; // Tổng tiền sản phẩm (VND)
let shippingFee = 0;

// Bước 1: Kiểm tra tồn kho
if (productStock > 0) {
  console.log('Xác nhận: Sản phẩm còn hàng.');

  // Bước 2: Tính phí vận chuyển rẽ nhánh nhiều mức giá
  if (orderTotal >= 500000) {
    shippingFee = 0;
    console.log('Đơn hàng đạt từ 500.000 VND: Miễn phí vận chuyển.');
  } else if (orderTotal >= 200000) {
    shippingFee = 15000;
    console.log('Đơn hàng từ 200.000 VND: Phí vận chuyển là 15.000 VND.');
  } else {
    shippingFee = 30000;
    console.log('Đơn hàng dưới 200.000 VND: Phí vận chuyển là 30.000 VND.');
  }

  const finalAmount = orderTotal + shippingFee;
  console.log('Tổng số tiền khách hàng cần thanh toán:', finalAmount, 'VND');
} else {
  console.log('Lỗi: Sản phẩm đã hết hàng, không thể tính toán đơn hàng.');
}

// Dữ liệu đầu vào từ yêu cầu thanh toán của người dùng
const orderTotal = 450000;
const customerRank = 'GOLD';
const productStock = 5;

// Kiểm tra và xử lý lỗi dữ liệu không hợp lệ (Edge Cases / Defensive Programming)
if (orderTotal <= 0) {
  console.log('[ERROR] Giá trị đơn hàng không hợp lệ. Số tiền phải lớn hơn 0.');
} else if (productStock <= 0) {
  console.log('[ERROR] Sản phẩm trong giỏ hàng đã hết. Vui lòng cập nhật lại giỏ hàng.');
} else {
  // Dữ liệu hợp lệ, tiến hành tính toán nghiệp vụ chính
  let discountRate = 0;

  // Xác định tỷ lệ giảm giá theo hạng thành viên
  if (customerRank === 'VIP') {
    discountRate = 0.20; // Giảm 20%
  } else if (customerRank === 'GOLD') {
    discountRate = 0.10; // Giảm 10%
  } else if (customerRank === 'SILVER') {
    discountRate = 0.05; // Giảm 5%
  } else {
    discountRate = 0;    // Thành viên phổ thông không giảm giá
  }

  // Tính toán số tiền chiết khấu
  const discountAmount = orderTotal * discountRate;
  const amountAfterDiscount = orderTotal - discountAmount;

  // Tính phí vận chuyển dựa trên giá trị sau giảm giá
  let shippingFee = 0;
  if (amountAfterDiscount >= 500000) {
    shippingFee = 0;
  } else if (amountAfterDiscount >= 200000) {
    shippingFee = 15000;
  } else {
    shippingFee = 30000;
  }

  const finalPayment = amountAfterDiscount + shippingFee;

  // In hóa đơn thanh toán chi tiết
  console.log('=== HÓA ĐƠN THANH TOÁN ===');
  console.log('Giá gốc đơn hàng:', orderTotal, 'VND');
  console.log('Hạng khách hàng:', customerRank);
  console.log('Số tiền được giảm:', discountAmount, 'VND');
  console.log('Phí giao hàng:', shippingFee, 'VND');
  console.log('TỔNG TIỀN PHẢI THANH TOÁN:', finalPayment, 'VND');
}

